-- Additive workflow schema. The application executes the equivalent
-- CREATE TABLE IF NOT EXISTS migration at startup and never deletes data.
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY,task_id TEXT UNIQUE NOT NULL,original_filename TEXT NOT NULL,storage_path TEXT NOT NULL,file_type TEXT NOT NULL,source_hash TEXT NOT NULL,purpose TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS questionnaire_tasks(id TEXT PRIMARY KEY,document_id TEXT NOT NULL,customer_name TEXT NOT NULL DEFAULT '',questionnaire_name TEXT NOT NULL DEFAULT '',company TEXT NOT NULL DEFAULT '',factory TEXT NOT NULL DEFAULT '',product TEXT NOT NULL DEFAULT '',business_scope TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',workflow_status TEXT NOT NULL DEFAULT 'uploaded',current_edit_version INTEGER NOT NULL DEFAULT 0,save_status TEXT NOT NULL DEFAULT 'saved',last_saved_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS document_blocks(task_id TEXT NOT NULL,block_id TEXT NOT NULL,kind TEXT NOT NULL,order_no INTEGER NOT NULL,text TEXT NOT NULL,location_json TEXT NOT NULL,structure_json TEXT NOT NULL,PRIMARY KEY(task_id,block_id));
CREATE TABLE IF NOT EXISTS questions(id TEXT PRIMARY KEY,task_id TEXT NOT NULL,parent_id TEXT,field_id TEXT NOT NULL,ordinal INTEGER NOT NULL,section TEXT NOT NULL DEFAULT '',original_text TEXT NOT NULL,question_text TEXT NOT NULL,input_type TEXT NOT NULL DEFAULT 'text',source_refs_json TEXT NOT NULL,answer_regions_json TEXT NOT NULL,review_status TEXT NOT NULL DEFAULT 'ready',updated_at TEXT NOT NULL,UNIQUE(task_id,field_id));
CREATE TABLE IF NOT EXISTS answers(question_id TEXT PRIMARY KEY,answer_text TEXT NOT NULL DEFAULT '',selected_options_json TEXT NOT NULL DEFAULT '[]',notes TEXT NOT NULL DEFAULT '',origin TEXT NOT NULL DEFAULT 'blank',manual_override INTEGER NOT NULL DEFAULT 0,match_id TEXT,confirmed INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS answer_options(id TEXT PRIMARY KEY,question_id TEXT NOT NULL,option_order INTEGER NOT NULL,text TEXT NOT NULL,value TEXT NOT NULL DEFAULT '',selected INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS knowledge_records(id TEXT PRIMARY KEY,canonical_question TEXT NOT NULL,original_question TEXT NOT NULL,answer TEXT NOT NULL,category TEXT NOT NULL DEFAULT '',section TEXT NOT NULL DEFAULT '',context TEXT NOT NULL DEFAULT '',applicable_scope_json TEXT NOT NULL DEFAULT '{}',source_file TEXT NOT NULL DEFAULT '',source_location_json TEXT NOT NULL DEFAULT '{}',language TEXT NOT NULL DEFAULT '',review_status TEXT NOT NULL DEFAULT 'pending',active INTEGER NOT NULL DEFAULT 0,allow_auto_reuse INTEGER NOT NULL DEFAULT 0,answer_version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS knowledge_aliases(id TEXT PRIMARY KEY,knowledge_id TEXT NOT NULL,alias TEXT NOT NULL,context TEXT NOT NULL DEFAULT '',applicable_scope_json TEXT NOT NULL DEFAULT '{}',confirmed INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS knowledge_versions(id TEXT PRIMARY KEY,knowledge_id TEXT NOT NULL,version INTEGER NOT NULL,answer TEXT NOT NULL,snapshot_json TEXT NOT NULL,reviewer TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,UNIQUE(knowledge_id,version));
CREATE TABLE IF NOT EXISTS matches(id TEXT PRIMARY KEY,task_id TEXT NOT NULL,question_id TEXT NOT NULL,knowledge_id TEXT,knowledge_version INTEGER,method TEXT NOT NULL,status TEXT NOT NULL,scope_result TEXT NOT NULL,coverage_complete INTEGER NOT NULL DEFAULT 0,reason TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS import_batches(id TEXT PRIMARY KEY,task_id TEXT,filename TEXT NOT NULL,file_type TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS import_items(id TEXT PRIMARY KEY,batch_id TEXT NOT NULL,original_question TEXT NOT NULL,canonical_question TEXT NOT NULL,answer TEXT NOT NULL DEFAULT '',section TEXT NOT NULL DEFAULT '',category TEXT NOT NULL DEFAULT '',context TEXT NOT NULL DEFAULT '',applicable_scope_json TEXT NOT NULL DEFAULT '{}',source_file TEXT NOT NULL,source_location_json TEXT NOT NULL DEFAULT '{}',language TEXT NOT NULL DEFAULT '',ambiguous INTEGER NOT NULL DEFAULT 0,empty_answer INTEGER NOT NULL DEFAULT 0,allow_auto_reuse INTEGER NOT NULL DEFAULT 0,review_status TEXT NOT NULL DEFAULT 'pending',answer_presence TEXT NOT NULL DEFAULT 'blank',pairing_validation TEXT NOT NULL DEFAULT 'unvalidated',validation_reasons_json TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS task_versions(task_id TEXT NOT NULL,version INTEGER NOT NULL,snapshot_file TEXT NOT NULL,kind TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(task_id,version));
CREATE TABLE IF NOT EXISTS exports(id TEXT PRIMARY KEY,task_id TEXT NOT NULL,task_version INTEGER NOT NULL,mode TEXT NOT NULL,file_path TEXT NOT NULL,filename TEXT NOT NULL,warnings_json TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL);
